"""The compaction step. Called whenever the window is over budget."""

SYSTEM = "system"
TASK = "task"
QUESTION = "question"
DURABLE = "durable"
TRACE = "trace"


class Item:
    def __init__(self, kind, text, score=0.0):
        self.kind = kind
        self.text = text
        self.score = score

    def __repr__(self):
        return f"Item({self.kind!r}, {self.text!r})"

    @property
    def tokens(self):
        return max(1, len(self.text.split()))


def compact(items, budget):
    """Return the items to keep, within budget, highest score first.

    Current behaviour: rank everything by score and take until full.
    """
    kept, used = [], 0
    for item in sorted(items, key=lambda i: -i.score):
        if used + item.tokens <= budget:
            kept.append(item)
            used += item.tokens
    return kept

